// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { TextField } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Inputs/TextField)

figma.connect(TextField, FIGMA_NODE_URL, {
  props: {
    placeholder: figma.string('placeholder'),
    iconStart: figma.boolean('hasIconStart', { true: figma.instance('iconStart'), false: undefined }),
    suffix: figma.string('suffix'),
    prefix: figma.string('prefix'),
    label: figma.string('label'),
    description: figma.string('description'),
    errorMessage: figma.string('errorMessage'),
    size: figma.enum('size', { 'sm': 'sm', 'md': 'md', 'lg': 'lg' }),
  },
  example: ({ label, placeholder, iconStart, suffix, prefix, description, errorMessage, size }) => (
    <TextField placeholder={placeholder} iconStart={iconStart} suffix={suffix} prefix={prefix} description={description} errorMessage={errorMessage} size={size}>{label}</TextField>
  ),
});
